        ans = l = 0
        trie = {}
        for r, y in enumerate(nums):
            node = trie
            for b in range(6, -1, -1):
                node = node.setdefault((y >> b) & 1, {})
            node['#'] = node.get('#', 0) + 1
            while nums[l] * 2 < y:
                x = nums[l]
                node = trie
                for b in range(6, -1, -1):
                    node = node[(x >> b) & 1]
                    node['#'] -= 1
                l += 1
            node = trie; cur = 0
            for b in range(6, -1, -1):
                bit = (y >> b) & 1
                if node.get(bit ^ 1) and node[bit ^ 1].get('#', 0):
                    cur |= 1 << b; node = node[bit ^ 1]
                else:
                    node = node[bit]
            ans = max(ans, cur)
        return ans

