class Solution {
public:
    int maximumStrongPairXor(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        struct T { int ch[2] = {0,0}; int cnt = 0; };
        vector<T> t(1); int ans = 0, l = 0;
        auto ins = [&](int x, int d) {
            int o = 0;
            for (int b = 6; b >= 0; b--) {
                int c = (x >> b) & 1;
                if (!t[o].ch[c]) { t.push_back(T()); t[o].ch[c] = t.size() - 1; }
                o = t[o].ch[c]; t[o].cnt += d;
            }
        };
        for (int r = 0; r < (int)nums.size(); r++) {
            ins(nums[r], 1);
            while (2 * nums[l] < nums[r]) { ins(nums[l], -1); l++; }
            int o = 0, cur = 0;
            for (int b = 6; b >= 0; b--) {
                int c = (nums[r] >> b) & 1;
                if (t[o].ch[c ^ 1] && t[t[o].ch[c ^ 1]].cnt) { cur |= 1 << b; o = t[o].ch[c ^ 1]; }
                else o = t[o].ch[c];
            }
            ans = max(ans, cur);
        }
        return ans;
    }
};

