class Solution {
    public int maximumStrongPairXor(int[] nums) {
        Arrays.sort(nums);
        int[][] ch = new int[4000][2]; int[] cnt = new int[4000]; int sz = 1;
        int ans = 0, l = 0;
        for (int r = 0; r < nums.length; r++) {
            int o = 0;
            for (int b = 6; b >= 0; b--) {
                int c = (nums[r] >> b) & 1;
                if (ch[o][c] == 0) { ch[o][c] = sz++; }
                o = ch[o][c]; cnt[o]++;
            }
            while (2 * nums[l] < nums[r]) {
                o = 0;
                for (int b = 6; b >= 0; b--) { o = ch[o][(nums[l] >> b) & 1]; cnt[o]--; }
                l++;
            }
            o = 0; int cur = 0;
            for (int b = 6; b >= 0; b--) {
                int c = (nums[r] >> b) & 1;
                if (ch[o][c ^ 1] != 0 && cnt[ch[o][c ^ 1]] > 0) { cur |= 1 << b; o = ch[o][c ^ 1]; }
                else o = ch[o][c];
            }
            ans = Math.max(ans, cur);
        }
        return ans;
    }
}

